  1	package @PKG@;
  2	
  3	/**
  4	 * Nxeon performance watchdog, pure half (no Bukkit types, unit-tested on its own by perf/test/NxPerfCoreTest.java).
  5	 * Injected by the Nxeon build service into every generated plugin as {@code <plugin package>.nxperf}; do not edit:
  6	 * the build service overwrites this file on every build. Holds the per-tick work budgets, the per-second rate limits
  7	 * and the lag judge that decides when the plugin's heavy features must pause.
  8	 */
  9	public final class NxPerfCore {
 10	  public static final String VERSION = "nxperf-1";
 11	
 12	  private NxPerfCore() {}
 13	
 14	  public static double clamp(double v, double lo, double hi) {
 15	    if (Double.isNaN(v)) return lo;
 16	    return Math.max(lo, Math.min(hi, v));
 17	  }
 18	
 19	  public static int clampInt(long v, int lo, int hi) {
 20	    return (int) Math.max(lo, Math.min(hi, v));
 21	  }
 22	
 23	  /** The perf.* config section, clamped to safe ranges (a config can tighten the limits, never remove them). */
 24	  public static final class Settings {
 25	    public boolean autoDisable = true;
 26	    public double tpsFloor = 15.0;
 27	    public int windowSeconds = 10;
 28	    public int maxWorkPerTick = 64;
 29	    public double maxMsPerTick = 25.0;
 30	    public double share = 0.25;
 31	    public double freezeMs = 2000.0;
 32	    public int maxEntitiesPerSecond = 5;
 33	    public int maxEntitiesPerChunk = 20;
 34	    public int maxQueue = 2000;
 35	    public int maxRadius = 48;
 36	    /** Entities this plugin's own code may spawn per second (listeners, NxPerf timers/queues); above it spawns are cancelled. */
 37	    public int maxSpawnsPerSecond = 50;
 38	    public int statusLogSeconds = 300;
 39	
 40	    public Settings clampAll() {
 41	      tpsFloor = clamp(tpsFloor, 5.0, 19.5);
 42	      windowSeconds = clampInt(windowSeconds, 3, 120);
 43	      maxWorkPerTick = clampInt(maxWorkPerTick, 1, 256);
 44	      maxMsPerTick = clamp(maxMsPerTick, 2.0, 45.0);
 45	      share = clamp(share, 0.05, 0.9);
 46	      freezeMs = clamp(freezeMs, 250.0, 10000.0);
 47	      maxEntitiesPerSecond = clampInt(maxEntitiesPerSecond, 1, 50);
 48	      maxEntitiesPerChunk = clampInt(maxEntitiesPerChunk, 1, 100);
 49	      maxQueue = clampInt(maxQueue, 10, 20000);
 50	      maxRadius = clampInt(maxRadius, 1, 64);
 51	      maxSpawnsPerSecond = clampInt(maxSpawnsPerSecond, 1, 500);
 52	      statusLogSeconds = clampInt(statusLogSeconds, 30, 3600);
 53	      return this;
 54	    }
 55	  }
 56	
 57	  /** Work units per server tick; resets when the tick number changes. */
 58	  public static final class Budget {
 59	    public final String name;
 60	    private int perTick;
 61	    private long tick = Long.MIN_VALUE;
 62	    private int used;
 63	    private long denied;
 64	    private long total;
 65	
 66	    public Budget(String name, int perTick) {
 67	      this.name = name;
 68	      this.perTick = Math.max(1, perTick);
 69	    }
 70	
 71	    public synchronized boolean take(long nowTick, int n) {
 72	      if (nowTick != tick) {
 73	        tick = nowTick;
 74	        used = 0;
 75	      }
 76	      if (n <= 0) return true;
 77	      if ((long) used + n > perTick) {
 78	        denied++;
 79	        return false;
 80	      }
 81	      used += n;
 82	      total += n;
 83	      return true;
 84	    }
 85	
 86	    public synchronized int remaining(long nowTick) {
 87	      return nowTick != tick ? perTick : Math.max(0, perTick - used);
 88	    }
 89	
 90	    public synchronized void setPerTick(int v) { perTick = Math.max(1, v); }
 91	    public synchronized int perTick() { return perTick; }
 92	    public synchronized long denied() { return denied; }
 93	    public synchronized long total() { return total; }
 94	  }
 95	
 96	  /** Token bucket: at most perSecond events per second (burst = one second's worth). */
 97	  public static final class Rate {
 98	    private double perSecond;
 99	    private double tokens;
100	    private long last = Long.MIN_VALUE;
101	    private long denied;
102	
103	    public Rate(double perSecond) {
104	      this.perSecond = Math.max(0.01, perSecond);
105	      this.tokens = this.perSecond;
106	    }
107	
108	    public synchronized boolean take(long nowNanos) {
109	      if (last != Long.MIN_VALUE) tokens = Math.min(perSecond, tokens + (nowNanos - last) / 1e9 * perSecond);
110	      last = nowNanos;
111	      if (tokens >= 1.0) {
112	        tokens -= 1.0;
113	        return true;
114	      }
115	      denied++;
116	      return false;
117	    }
118	
119	    public synchronized void setPerSecond(double v) { perSecond = Math.max(0.01, v); tokens = Math.min(tokens, perSecond); }
120	    public synchronized long denied() { return denied; }
121	  }
122	
123	  /** Verdicts of the lag judge. */
124	  public static final int NONE = 0, TPS = 1, BUDGET = 2;
125	
126	  /**
127	   * One sample per wall-clock second: the server's measured TPS and this plugin's own main-thread milliseconds per tick.
128	   * TPS verdict: for the whole window TPS stayed under the floor AND this plugin used at least `share` of each tick.
129	   * BUDGET verdict: for the whole window this plugin used more than maxMsPerTick per tick (even if TPS held up).
130	   * Low TPS with a small share is somebody else's lag: never a pause (lowWithoutUs reports it).
131	   */
132	  public static final class Judge {
133	    private final double[] tps;
134	    private final double[] own;
135	    private int next;
136	    private int count;
137	
138	    public Judge(int capacity) {
139	      tps = new double[Math.max(4, capacity)];
140	      own = new double[tps.length];
141	    }
142	
143	    public void reset() { next = 0; count = 0; }
144	
145	    /** A tick takes 1000/tps ms when the server is behind, at least 50 ms otherwise. */
146	    public static double tickMs(double tpsSample) {
147	      return Math.max(50.0, 1000.0 / Math.max(0.05, tpsSample));
148	    }
149	
150	    public int add(double tpsSample, double ownMsPerTick, Settings s) {
151	      tps[next] = tpsSample;
152	      own[next] = Math.max(0, ownMsPerTick);
153	      next = (next + 1) % tps.length;
154	      if (count < tps.length) count++;
155	      int w = Math.min(s.windowSeconds, tps.length);
156	      if (count < w) return NONE;
157	      boolean low = true, hog = true;
158	      for (int i = 1; i <= w; i++) {
159	        int k = (next - i + tps.length) % tps.length;
160	        double share = own[k] / tickMs(tps[k]);
161	        if (!(tps[k] < s.tpsFloor && share >= s.share)) low = false;
162	        if (!(own[k] > s.maxMsPerTick)) hog = false;
163	      }
164	      return low ? TPS : hog ? BUDGET : NONE;
165	    }
166	
167	    /** TPS under the floor for the whole window while this plugin's share stayed small. */
168	    public boolean lowWithoutUs(Settings s) {
169	      int w = Math.min(s.windowSeconds, tps.length);
170	      if (count < w) return false;
171	      for (int i = 1; i <= w; i++) {
172	        int k = (next - i + tps.length) % tps.length;
173	        if (!(tps[k] < s.tpsFloor && own[k] / tickMs(tps[k]) < s.share)) return false;
174	      }
175	      return true;
176	    }
177	
178	    public int samples() { return count; }
179	  }
180	
181	  /** "12.34" with a dot whatever the server locale (log lines are parsed by Nxeon's post-install watch). */
182	  public static String fmt(double v) {
183	    long r = Math.round(v * 100.0);
184	    String sign = r < 0 ? "-" : "";
185	    r = Math.abs(r);
186	    long cents = r % 100;
187	    return sign + (r / 100) + "." + (cents < 10 ? "0" : "") + cents;
188	  }
189	}
  1	// Cyrus perf safety (2026-10-11): the LIVING AUDIT of the no-model emitters (gameplay designers, motion, data packs,
  2	// worldgen) against the perf rules every generated plugin now follows (services/modbuilder/prompts.js rule 10):
  3	//   R1 bounded work per tick / per activation     R2 entity spawns capped (per activation / plugin-wide)
  4	//   R3 particles capped                            R4 explosions / projectiles capped
  5	//   R5 no world-wide iteration, radius capped      R6 repeating work at a bounded cadence (no unbounded tick work)
  6	//   R7 no recursion through own events / calls     R8 growing state bounded
  7	// Each row reads the REAL constants, so a cap that is loosened (or removed) changes this table and its test
  8	// (test/cyrus-perf-caps.test.ts) fails until someone looks. Pure data; nothing here is enforced at runtime.
  9	import { BUDGET, CAPS, RUNTIME_CAPS } from "../designer/spec";
 10	import { BOSS_LIMITS, BOSS_CAPS } from "../designer/boss/spec";
 11	import { HUD_CAPS } from "../designer/hud/spec";
 12	import { MOTION_LIMITS } from "../motion/spec";
 13	import { FN_LIMITS } from "../datapack/functions";
 14	import { WORLDGEN_LIMITS } from "../datapack/worldgen/spec";
 15	
 16	export type PerfRuleId = "R1" | "R2" | "R3" | "R4" | "R5" | "R6" | "R7" | "R8";
 17	export type CapRow = { emitter: string; rule: PerfRuleId; cap: string; value: number | string; status: "ok" | "added-2026-10-11" | "owner-decision" | "gap"; note?: string };
 18	
 19	export const PERF_RULE_TEXT: Record<PerfRuleId, string> = {
 20	  R1: "bounded work per tick / per activation", R2: "entity spawns capped", R3: "particles capped", R4: "explosions and projectiles capped",
 21	  R5: "no world-wide iteration; radius capped", R6: "repeating work at a bounded cadence", R7: "no recursion through own events or calls", R8: "growing state bounded",
 22	};
 23	
 24	export function perfCapAudit(): CapRow[] {
 25	  return [
 26	    // item + ability designer (lib/cyrus/designer)
 27	    { emitter: "item designer", rule: "R1", cap: "actions per activation", value: BUDGET.actions, status: "ok" },
 28	    { emitter: "item designer", rule: "R2", cap: "entities per activation", value: BUDGET.entities, status: "ok" },
 29	    { emitter: "item designer", rule: "R3", cap: "particles per activation", value: BUDGET.particles, status: "ok" },
 30	    { emitter: "item designer", rule: "R3", cap: "particles per action", value: CAPS.particleCount[1], status: "ok" },
 31	    { emitter: "item designer", rule: "R4", cap: "projectiles per activation", value: BUDGET.projectiles, status: "ok" },
 32	    { emitter: "item designer", rule: "R5", cap: "nearby query radius (blocks)", value: CAPS.queryNearbyRadius[1], status: "ok" },
 33	    { emitter: "item designer", rule: "R5", cap: "nearby query max entities", value: CAPS.queryMax[1], status: "ok" },
 34	    { emitter: "item designer", rule: "R6", cap: "held_interval period (ticks, minimum)", value: CAPS.periodTicks[0], status: "ok" },
 35	    { emitter: "item designer", rule: "R6", cap: "click abilities without a cooldown: minimum gap per player (ticks)", value: "none (cooldown 0 allowed)", status: "owner-decision", note: "a cooldown-0 click ability fires on every click packet (still capped per activation). Proposed floor: 2 ticks per player in Ability.fire; NOT applied because it changes the byte-identical R3 golden jars of every existing designer mod (OWNER-ACTIONS)" },
 36	    { emitter: "item designer", rule: "R6", cap: "live delayed tasks plugin-wide", value: RUNTIME_CAPS.liveTasks, status: "ok" },
 37	    { emitter: "item designer", rule: "R7", cap: "re-entrant activation guard", value: "Designer.enter/exit per player", status: "ok" },
 38	    { emitter: "item designer", rule: "R8", cap: "marks plugin-wide", value: RUNTIME_CAPS.marksTotal, status: "ok" },
 39	    // bosses + encounters
 40	    { emitter: "boss designer", rule: "R2", cap: "summons per attack", value: BOSS_LIMITS.summonsPerAttack, status: "ok" },
 41	    { emitter: "boss designer", rule: "R2", cap: "live minions plugin-wide", value: BOSS_LIMITS.liveMinions, status: "ok" },
 42	    { emitter: "boss designer", rule: "R2", cap: "live bosses plugin-wide", value: BOSS_LIMITS.liveBosses, status: "ok" },
 43	    { emitter: "boss designer", rule: "R2", cap: "encounter mobs plugin-wide", value: BOSS_LIMITS.encounterMobs, status: "ok" },
 44	    { emitter: "boss designer", rule: "R5", cap: "arena radius (blocks)", value: BOSS_CAPS.arenaRadius[1], status: "ok" },
 45	    { emitter: "boss designer", rule: "R6", cap: "one shared AI timer (ticks)", value: BOSS_LIMITS.aiPeriodTicks, status: "ok" },
 46	    { emitter: "boss designer", rule: "R6", cap: "attack interval (ticks, minimum)", value: BOSS_CAPS.intervalTicks[0], status: "ok" },
 47	    // HUD
 48	    { emitter: "HUD designer", rule: "R6", cap: "update period (ticks, minimum)", value: HUD_CAPS.updateTicks[0], status: "ok" },
 49	    // motion props
 50	    { emitter: "motion props", rule: "R2", cap: "display entities per prop (nodes)", value: MOTION_LIMITS.nodes, status: "ok" },
 51	    { emitter: "motion props", rule: "R3", cap: "particle emitters per prop", value: MOTION_LIMITS.emitters, status: "ok" },
 52	    // data pack functions
 53	    { emitter: "data pack", rule: "R1", cap: "commands every tick (whole call graph)", value: FN_LIMITS.maxTickCommands, status: "ok" },
 54	    { emitter: "data pack", rule: "R2", cap: "unconditional summon in a tick function", value: "refused", status: "added-2026-10-11", note: "was a warning: 20 entities per second, forever" },
 55	    { emitter: "data pack", rule: "R3", cap: "particles per command", value: FN_LIMITS.maxParticleCount, status: "added-2026-10-11" },
 56	    { emitter: "data pack", rule: "R3", cap: "particles per command in a tick function", value: FN_LIMITS.maxTickParticleCount, status: "added-2026-10-11" },
 57	    { emitter: "data pack", rule: "R1", cap: "fill/clone blocks per command in a tick function", value: FN_LIMITS.maxTickFillVolume, status: "added-2026-10-11" },
 58	    { emitter: "data pack", rule: "R1", cap: "fill/clone blocks per command (warning above)", value: FN_LIMITS.warnFillVolume, status: "added-2026-10-11" },
 59	    { emitter: "data pack", rule: "R5", cap: "execute as/at @e without a filter in a tick function", value: "warning", status: "added-2026-10-11" },
 60	    { emitter: "data pack", rule: "R5", cap: "forceloaded chunks per pack", value: FN_LIMITS.maxForceloadAdds, status: "ok" },
 61	    { emitter: "data pack", rule: "R7", cap: "call depth (no recursion)", value: FN_LIMITS.maxCallDepth, status: "ok" },
 62	    { emitter: "data pack", rule: "R6", cap: "schedule commands per pack", value: FN_LIMITS.maxScheduleCommands, status: "ok" },
 63	    // worldgen
 64	    { emitter: "worldgen", rule: "R1", cap: "placement attempts per chunk per biome", value: WORLDGEN_LIMITS.attemptsPerBiome, status: "ok" },
 65	    { emitter: "worldgen", rule: "R1", cap: "per-chunk cost ceiling (cost units)", value: WORLDGEN_LIMITS.maxCost, status: "ok" },
 66	    { emitter: "worldgen", rule: "R2", cap: "spawn entries per biome", value: WORLDGEN_LIMITS.spawnsPerBiome, status: "ok" },
 67	    { emitter: "worldgen", rule: "R1", cap: "structure template blocks", value: WORLDGEN_LIMITS.templateBlocks, status: "ok" },
 68	  ];
 69	}
 70	
 71	/** Rules with no row at all for an emitter that can do that kind of work (the audit's own gap list). */
 72	export function perfCapGaps(rows: CapRow[] = perfCapAudit()): string[] {
 73	  return rows.filter((r) => r.status === "gap").map((r) => `${r.emitter} ${r.rule}: ${r.cap}`);
 74	}

