 36	/**
 37	 * Nxeon performance watchdog (Bukkit half). Injected by the Nxeon build service into every generated plugin as
 38	 * {@code <plugin package>.nxperf.NxPerf} and started from onEnable; do not edit (overwritten on every build).
 39	 *
 40	 * What it does without any help from the plugin:
 41	 *  - samples the server's real tick rate every second (and Paper's TPS / MSPT for the status);
 42	 *  - measures the main-thread time of this plugin's own event listeners (each one is wrapped once, after onEnable);
 43	 *  - when TPS stays under perf.tps-floor for perf.window-seconds while this plugin uses at least perf.share of each
 44	 *    tick, or the plugin alone uses more than perf.max-ms-per-tick for the whole window, or one tick of its listeners
 45	 *    takes longer than perf.freeze-ms: PAUSES the plugin's heavy features (its costliest listeners, its NxPerf timers
 46	 *    and queues), never the server and never another plugin, logs "[NxPerf] PAUSED ..." and tells online operators;
 47	 *  - "/<command> perf status|pause|resume" (or /<plugin>perf when the plugin has no command), operators/console only.
 48	 * What the plugin uses on purpose (required by the build rules): take()/spawnAllowed()/queue()/timer()/enter()/radius().
 49	 */
 50	public final class NxPerf {
 51	  private NxPerf() {}
 52	
 53	  private static Plugin plugin;
 54	  private static final NxPerfCore.Settings S = new NxPerfCore.Settings();
 55	  private static final NxPerfCore.Judge JUDGE = new NxPerfCore.Judge(120);
 56	  private static final Map<String, NxPerfCore.Budget> BUDGETS = new LinkedHashMap<>();
 57	  private static final Map<String, NxPerfCore.Rate> RATES = new HashMap<>();
 58	  private static final Map<String, Integer> DEPTH = new HashMap<>();
 59	  private static final List<Timed> TIMED = new ArrayList<>();
 60	  private static final List<Timed> PAUSED_LISTENERS = new ArrayList<>();
 61	  private static final List<Timer> TIMERS = new ArrayList<>();
 62	  private static final List<Queue<?>> QUEUES = new ArrayList<>();
 63	  private static final List<Runnable> ON_PAUSE = new ArrayList<>();
 64	  private static final List<Runnable> ON_RESUME = new ArrayList<>();
 65	  private static volatile boolean paused;
 66	  private static String pauseReason;
 67	  private static long ownNanosTick, ownNanosSecond, secondStart;
 68	  private static int ticksSecond, secondsSinceStatus, seconds;
 69	  private static long enabledAtMs;
 70	  private static double lastTps = 20.0, lastOwnMs;
 71	  private static boolean lowNoted;
 72	  private static String commandLabel;
 73	  /** > 0 while this plugin's own code runs (a wrapped listener, an NxPerf timer or queue): spawns then count as ours. */
 74	  private static int ownDepth;
 75	  private static int ownSpawnsSecond, deniedSpawnsSecond, deniedSeconds;
 76	  private static long deniedSpawnsTotal;
 77	
 78	  // ------------------------------------------------------------------ lifecycle ----
 79	
 80	  /** Called first thing in onEnable (inserted by the build service). Safe to call again after a reload. */
 81	  public static void init(Plugin p) {
 82	    plugin = p;
 83	    BUDGETS.clear(); RATES.clear(); DEPTH.clear(); TIMED.clear(); PAUSED_LISTENERS.clear(); TIMERS.clear(); QUEUES.clear();
 84	    ON_PAUSE.clear(); ON_RESUME.clear();
 85	    paused = false; pauseReason = null; ownNanosTick = 0; ownNanosSecond = 0; secondStart = 0; ticksSecond = 0;
 86	    secondsSinceStatus = 0; seconds = 0; lowNoted = false; commandLabel = null; JUDGE.reset();
 87	    ownDepth = 0; ownSpawnsSecond = 0; deniedSpawnsSecond = 0; deniedSeconds = 0; deniedSpawnsTotal = 0;
 88	    enabledAtMs = System.currentTimeMillis();
 89	    readSettings();
 90	    p.getServer().getPluginManager().registerEvents(new SpawnGuard(), p);
 91	    Bukkit.getScheduler().runTaskTimer(p, NxPerf::tick, 1L, 1L);
 92	    Bukkit.getScheduler().runTaskLater(p, () -> { wrapListeners(); hookCommand(); }, 1L);
 93	    p.getLogger().info("[NxPerf] watchdog " + NxPerfCore.VERSION + " on: pauses heavy features below " + NxPerfCore.fmt(S.tpsFloor)
 94	        + " TPS for " + S.windowSeconds + " s (perf.auto-disable=" + S.autoDisable + ")");
 95	  }
 96	
 97	  private static void readSettings() {
 98	    try {
 99	      FileConfiguration c = plugin.getConfig();
100	      S.autoDisable = c.getBoolean("perf.auto-disable", true);
101	      S.tpsFloor = c.getDouble("perf.tps-floor", 15.0);
102	      S.windowSeconds = c.getInt("perf.window-seconds", 10);
103	      S.maxWorkPerTick = c.getInt("perf.max-work-per-tick", 64);
104	      S.maxMsPerTick = c.getDouble("perf.max-ms-per-tick", 25.0);
105	      S.share = c.getDouble("perf.share", 0.25);
106	      S.maxEntitiesPerSecond = c.getInt("perf.max-entities-per-second", 5);
107	      S.maxEntitiesPerChunk = c.getInt("perf.max-entities-per-chunk", 20);
108	      S.maxQueue = c.getInt("perf.max-queue", 2000);
109	      S.maxRadius = c.getInt("perf.max-radius", 48);
110	      S.statusLogSeconds = c.getInt("perf.status-log-seconds", 300);
111	      S.maxSpawnsPerSecond = c.getInt("perf.max-spawns-per-second", 50);
112	    } catch (RuntimeException e) {
113	      // keep the defaults: a broken config never switches the watchdog off
114	    }
115	    S.clampAll();
116	    for (NxPerfCore.Budget b : BUDGETS.values()) b.setPerTick(S.maxWorkPerTick);
117	  }
118	
119	  private static void tick() {
120	    long now = System.nanoTime();
121	    if (secondStart == 0) secondStart = now;
122	    if (!paused && S.autoDisable && ownNanosTick / 1e6 > S.freezeMs) pause("freeze", "one tick of this plugin's listeners took " + NxPerfCore.fmt(ownNanosTick / 1e6) + " ms");
123	    ownNanosTick = 0;
124	    for (Queue<?> q : QUEUES) q.drain();
125	    ticksSecond++;
126	    if (now - secondStart < 1_000_000_000L) return;
127	    double secs = (now - secondStart) / 1e9;
128	    lastTps = Math.min(20.0, ticksSecond / secs);
129	    lastOwnMs = ticksSecond > 0 ? ownNanosSecond / 1e6 / ticksSecond : 0;
130	    ownNanosSecond = 0; ticksSecond = 0; secondStart = now; seconds++;
131	    for (Timed t : TIMED) t.roll();
132	    // spawns caused by this plugin's own code above the cap were cancelled; 3 such seconds in a row = runaway spawning
133	    deniedSeconds = deniedSpawnsSecond > 0 ? deniedSeconds + 1 : 0;
134	    int spawnedLast = ownSpawnsSecond, deniedLast = deniedSpawnsSecond;
135	    ownSpawnsSecond = 0; deniedSpawnsSecond = 0;
136	    if (!paused && S.autoDisable && deniedSeconds >= 3) {
137	      pause("entities", "this plugin tried to spawn more than " + S.maxSpawnsPerSecond + " entities per second for 3 s (last second: " + (spawnedLast + deniedLast) + ")");
138	    }
139	    int v = JUDGE.add(lastTps, lastOwnMs, S);
140	    if (!paused && S.autoDisable && v != NxPerfCore.NONE) {
141	      pause(v == NxPerfCore.TPS ? "tps" : "budget", "TPS " + NxPerfCore.fmt(lastTps) + " for " + S.windowSeconds + " s, this plugin " + NxPerfCore.fmt(lastOwnMs) + " ms per tick");
142	    } else if (!paused && JUDGE.lowWithoutUs(S)) {
143	      if (!lowNoted) plugin.getLogger().info("[NxPerf] LAG plugin=" + plugin.getName() + " tps=" + NxPerfCore.fmt(lastTps) + " own_ms=" + NxPerfCore.fmt(lastOwnMs) + " (not caused by this plugin)");
144	      lowNoted = true;
145	    } else if (lastTps >= S.tpsFloor) {
146	      lowNoted = false;
147	    }
148	    if (seconds % 5 == 0) wrapListeners();
149	    if (seconds % 30 == 0) readSettings();
150	    int every = System.currentTimeMillis() - enabledAtMs < 15 * 60_000L ? 30 : S.statusLogSeconds;
151	    if (++secondsSinceStatus >= every) {
152	      secondsSinceStatus = 0;
153	      plugin.getLogger().info("[NxPerf] status v=" + NxPerfCore.VERSION + " plugin=" + plugin.getName() + " tps=" + NxPerfCore.fmt(lastTps)
154	          + " paper_tps=" + NxPerfCore.fmt(paperTps()) + " mspt=" + NxPerfCore.fmt(paperMspt()) + " own_ms=" + NxPerfCore.fmt(lastOwnMs) + " spawns_denied=" + deniedSpawnsTotal + " paused=" + paused);
155	    }
156	  }
