168	  /** A listener of this plugin with its main-thread time measured; the original keeps doing the work. */
169	  private static final class Timed extends RegisteredListener {
170	    final RegisteredListener inner;
171	    final HandlerList list;
172	    String event = "?";
173	    long nanosSecond, calls;
174	    double recentMs;
175	
176	    Timed(RegisteredListener in, HandlerList list) {
177	      super(in.getListener(), (l, e) -> { }, in.getPriority(), in.getPlugin(), in.isIgnoringCancelled());
178	      this.inner = in;
179	      this.list = list;
180	    }
181	
182	    @Override
183	    public void callEvent(Event e) throws EventException {
184	      if (!Bukkit.isPrimaryThread()) {
185	        inner.callEvent(e);
186	        return;
187	      }
188	      long t = System.nanoTime();
189	      ownDepth++;
190	      try {
191	        inner.callEvent(e);
192	      } finally {
193	        ownDepth--;
194	        long d = System.nanoTime() - t;
195	        nanosSecond += d;
196	        calls++;
197	        ownNanosTick += d;
198	        ownNanosSecond += d;
199	        if (event.equals("?")) event = e.getEventName();
200	      }
201	    }
202	
203	    void roll() {
204	      recentMs = recentMs * 0.8 + nanosSecond / 1e6;
205	      nanosSecond = 0;
206	    }
207	
208	    String label() { return inner.getListener().getClass().getSimpleName() + "/" + event; }
209	  }
210	
211	  private static void wrapListeners() {
212	    if (plugin == null) return;
213	    for (HandlerList hl : new ArrayList<>(HandlerList.getHandlerLists())) {
214	      for (RegisteredListener rl : hl.getRegisteredListeners()) {
215	        if (rl.getPlugin() != plugin || rl instanceof Timed || rl.getListener() instanceof SpawnGuard) continue;
216	        Timed t = new Timed(rl, hl);
217	        hl.unregister(rl);
218	        hl.register(t);
219	        TIMED.add(t);
220	      }
221	    }
222	  }
