224	  /** Caps the entities this plugin's own code spawns (perf.max-spawns-per-second); never touches other plugins' or vanilla spawns. */
225	  public static final class SpawnGuard implements Listener {
226	    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = true)
227	    public void onSpawn(EntitySpawnEvent e) {
228	      if (ownDepth <= 0 || !Bukkit.isPrimaryThread() || e.getEntity() instanceof Player) return;
229	      if (paused || ownSpawnsSecond >= S.maxSpawnsPerSecond) {
230	        e.setCancelled(true);
231	        deniedSpawnsSecond++;
232	        deniedSpawnsTotal++;
233	        return;
234	      }
235	      ownSpawnsSecond++;
236	    }
237	  }
