240	
241	  /** Pause the plugin's heavy features (never the server, never another plugin). */
242	  public static synchronized void pause(String reason, String detail) {
243	    if (paused || plugin == null) return;
244	    paused = true;
245	    pauseReason = reason;
246	    List<Timed> byCost = new ArrayList<>(TIMED);
247	    byCost.sort(Comparator.comparingDouble((Timed t) -> -t.recentMs));
248	    double total = 0;
249	    for (Timed t : byCost) total += t.recentMs;
250	    double acc = 0;
251	    List<String> names = new ArrayList<>();
252	    for (Timed t : byCost) {
253	      if (total <= 0 || t.recentMs <= 0) break;
254	      t.list.unregister(t);
255	      PAUSED_LISTENERS.add(t);
256	      names.add(t.label());
257	      acc += t.recentMs;
258	      if (acc >= total * 0.9) break;
259	    }
260	    for (Timer t : TIMERS) t.stop();
261	    for (Queue<?> q : QUEUES) q.clear();
262	    for (Runnable r : ON_PAUSE) {
263	      try { r.run(); } catch (RuntimeException e) { plugin.getLogger().warning("[NxPerf] a pause hook failed: " + e); }
264	    }
265	    String line = "[NxPerf] PAUSED plugin=" + plugin.getName() + " reason=" + reason + " tps=" + NxPerfCore.fmt(lastTps) + " own_ms=" + NxPerfCore.fmt(lastOwnMs)
266	        + " listeners=" + (names.isEmpty() ? "none" : String.join(",", names)) + " timers=" + TIMERS.size() + " detail=" + detail;
267	    plugin.getLogger().warning(line);
268	    tellOps("Performance safety paused this mod's heavy features (" + detail + "). The server keeps running. Check with /" + label() + " perf status, resume with /" + label() + " perf resume.");
269	  }
270	
271	  public static synchronized void resume(String by) {
272	    if (!paused || plugin == null) return;
273	    for (Timed t : PAUSED_LISTENERS) t.list.register(t);
274	    PAUSED_LISTENERS.clear();
275	    for (Timer t : TIMERS) t.start();
276	    for (Runnable r : ON_RESUME) {
277	      try { r.run(); } catch (RuntimeException e) { plugin.getLogger().warning("[NxPerf] a resume hook failed: " + e); }
278	    }
279	    paused = false;
280	    pauseReason = null;
281	    JUDGE.reset();
282	    plugin.getLogger().warning("[NxPerf] RESUMED plugin=" + plugin.getName() + " by=" + by);
283	  }
