357	  /** A bounded work queue drained every tick within the budget `name`. offer() is false when full or paused. */
358	  public static <T> Queue<T> queue(String name, Consumer<T> worker) {
359	    Queue<T> q = new Queue<>(name, worker);
360	    QUEUES.add(q);
361	    return q;
362	  }
363	
364	  public static final class Queue<T> {
365	    private final String name;
366	    private final Consumer<T> worker;
367	    private final ArrayDeque<T> items = new ArrayDeque<>();
368	    private long dropped;
369	    private boolean warned;
370	
371	    Queue(String name, Consumer<T> worker) {
372	      this.name = name;
373	      this.worker = worker;
374	    }
375	
376	    public boolean offer(T item) {
377	      if (paused || items.size() >= S.maxQueue) {
378	        dropped++;
379	        if (!warned && !paused) {
380	          warned = true;
381	          plugin.getLogger().warning("[NxPerf] queue " + name + " is full (" + S.maxQueue + "); extra work is dropped");
382	        }
383	        return false;
384	      }
385	      items.add(item);
386	      return true;
387	    }
388	
389	    public int size() { return items.size(); }
390	
391	    public long dropped() { return dropped; }
392	
393	    void clear() { dropped += items.size(); items.clear(); }
394	
395	    void drain() {
396	      if (paused || items.isEmpty()) return;
397	      long t = System.nanoTime();
398	      ownDepth++;
399	      try {
400	        while (!items.isEmpty() && take(name, 1)) {
401	          T x = items.poll();
402	          try {
403	            worker.accept(x);
404	          } catch (RuntimeException e) {
405	            plugin.getLogger().warning("[NxPerf] queue " + name + " task failed: " + e);
406	          }
407	        }
408	      } finally {
409	        ownDepth--;
410	      }
411	      long d = System.nanoTime() - t;
412	      ownNanosTick += d;
413	      ownNanosSecond += d;
414	    }
415	  }
416	
417	  /** A repeating task that is measured and paused with the heavy features. period is clamped to at least 1 tick. */
418	  public static Timer timer(String name, long delayTicks, long periodTicks, Runnable work) {
419	    Timer t = new Timer(name, Math.max(0, delayTicks), Math.max(1, periodTicks), work);
420	    TIMERS.add(t);
421	    if (!paused) t.start();
422	    return t;
423	  }
