425	  public static final class Timer {
426	    private final String name;
427	    private final long delay, period;
428	    private final Runnable work;
429	    private BukkitTask task;
430	
431	    Timer(String name, long delay, long period, Runnable work) {
432	      this.name = name;
433	      this.delay = delay;
434	      this.period = period;
435	      this.work = work;
436	    }
437	
438	    void start() {
439	      if (task != null || plugin == null) return;
440	      task = Bukkit.getScheduler().runTaskTimer(plugin, () -> {
441	        if (paused) return;
442	        long t = System.nanoTime();
443	        ownDepth++;
444	        try {
445	          work.run();
446	        } finally {
447	          ownDepth--;
448	          long d = System.nanoTime() - t;
449	          ownNanosTick += d;
450	          ownNanosSecond += d;
451	        }
452	      }, delay, period);
453	    }
454	
455	    void stop() {
456	      if (task != null) task.cancel();
457	      task = null;
458	    }
459	
460	    public void cancel() {
461	      stop();
462	      TIMERS.remove(this);
463	    }
464	
465	    public String name() { return name; }
466	  }
