474	  private static void hookCommand() {
475	    if (plugin == null) return;
476	    PluginCommand own = null;
477	    String want = plugin.getName().toLowerCase(Locale.ROOT);
478	    for (Map.Entry<String, Command> e : Bukkit.getCommandMap().getKnownCommands().entrySet()) {
479	      if (!(e.getValue() instanceof PluginCommand pc) || pc.getPlugin() != plugin || e.getKey().contains(":")) continue;
480	      if (own == null || pc.getName().equals(want) || (!own.getName().equals(want) && pc.getName().compareTo(own.getName()) < 0)) own = pc;
481	    }
482	    if (own != null) {
483	      final CommandExecutor inner = own.getExecutor();
484	      own.setExecutor((sender, cmd, lbl, args) -> {
485	        if (args.length > 0 && args[0].equalsIgnoreCase("perf")) return perfCommand(sender, args);
486	        return inner.onCommand(sender, cmd, lbl, args);
487	      });
488	      commandLabel = own.getName();
489	      return;
490	    }
491	    String name = want + "perf";
492	    Bukkit.getCommandMap().register(want, new Command(name, "Performance safety status for " + plugin.getName(), "/" + name + " [status|pause|resume]", new ArrayList<>()) {
493	      @Override
494	      public boolean execute(CommandSender sender, String lbl, String[] args) {
495	        String[] a = new String[args.length + 1];
496	        a[0] = "perf";
497	        System.arraycopy(args, 0, a, 1, args.length);
498	        return perfCommand(sender, a);
499	      }
500	    });
501	    commandLabel = name;
502	  }
