504	  private static boolean perfCommand(CommandSender sender, String[] args) {
505	    String perm = plugin.getName().toLowerCase(Locale.ROOT) + ".perf";
506	    if (!(sender instanceof ConsoleCommandSender) && !sender.isOp() && !sender.hasPermission(perm)) {
507	      sender.sendMessage(Component.text("You need " + perm + " (or operator) for this.", NamedTextColor.RED));
508	      return true;
509	    }
510	    String sub = args.length > 1 ? args[1].toLowerCase(Locale.ROOT) : "status";
511	    switch (sub) {
512	      case "pause", "off" -> {
513	        pause("manual", "paused by " + sender.getName());
514	        sender.sendMessage(Component.text("Heavy features paused.", NamedTextColor.YELLOW));
515	      }
516	      case "resume", "on" -> {
517	        resume(sender.getName());
518	        sender.sendMessage(Component.text("Heavy features resumed.", NamedTextColor.GREEN));
519	      }
520	      default -> {
521	        sender.sendMessage(Component.text("NxPerf " + plugin.getName() + ": TPS " + NxPerfCore.fmt(lastTps) + " (Paper " + NxPerfCore.fmt(paperTps()) + "), MSPT "
522	            + NxPerfCore.fmt(paperMspt()) + ", this plugin " + NxPerfCore.fmt(lastOwnMs) + " ms/tick, " + (paused ? "PAUSED (" + pauseReason + ")" : "running"), NamedTextColor.AQUA));
523	        List<Timed> byCost = new ArrayList<>(TIMED);
524	        byCost.sort(Comparator.comparingDouble((Timed t) -> -t.recentMs));
525	        for (int i = 0; i < Math.min(3, byCost.size()); i++) {
526	          Timed t = byCost.get(i);
527	          sender.sendMessage(Component.text("  " + t.label() + ": " + NxPerfCore.fmt(t.recentMs / 5.0) + " ms/s, " + t.calls + " calls", NamedTextColor.GRAY));
528	        }
529	        for (NxPerfCore.Budget b : BUDGETS.values()) sender.sendMessage(Component.text("  budget " + b.name + ": " + b.perTick() + "/tick, denied " + b.denied(), NamedTextColor.GRAY));
530	        sender.sendMessage(Component.text("  floor " + NxPerfCore.fmt(S.tpsFloor) + " TPS for " + S.windowSeconds + " s, auto-disable " + S.autoDisable
531	            + ", max work/tick " + S.maxWorkPerTick + ", spawns/s " + S.maxSpawnsPerSecond + " (denied " + deniedSpawnsTotal + "). /" + label() + " perf pause|resume", NamedTextColor.GRAY));
532	      }
533	    }
534	    return true;
535	  }
