     1	"use strict";
     2	// Cyrus perf safety (2026-10-11, after the ChunkMirror incident): the WATCHDOG injection and the PERF pre-check.
     3	//
     4	// inject(ws, rec): before every javac of a generated (not imported) plugin, place the audited watchdog sources
     5	//   (perf/src/NxPerf*.java) into <main package>.nxperf, call NxPerf.init(this) first thing in onEnable (added when
     6	//   missing), point any NxPerf import at that package, and append the perf: section to config.yml. The files are
     7	//   overwritten on every round, so the model can never ship a modified watchdog. Pure file edits, deterministic.
     8	// perfcheck(files): source heuristics for unbounded work (world-wide iteration, spawns/explosions in loops, raw
     9	//   repeating tasks, recursion through the plugin's own events, huge radius/per-tick literals) without the NxPerf
    10	//   bounds. Hits go back to the model like pre-check problems (each once); they never block a build on their own.
    11	// MB_PERF_SAFETY=0 turns both off (default on).
    12	
    13	const fs = require("fs");
    14	const path = require("path");
    15	
    16	const PERF_VERSION = "nxperf-1";
    17	const SRC_DIR = path.join(__dirname, "perf", "src");
    18	const FILES = ["NxPerfCore.java", "NxPerf.java"];
    19	const enabled = (env = process.env) => !/^(0|false|off)$/i.test(String(env.MB_PERF_SAFETY ?? "").trim());
    20	
    21	const CONFIG_SECTION = `
    22	# Performance safety (added by Nxeon). If the server stays under tps-floor for window-seconds while this mod
    23	# causes the lag, its heavy features pause (the server keeps running). /<command> perf status shows the numbers.
    24	perf:
    25	  auto-disable: true
    26	  tps-floor: 15.0
    27	  window-seconds: 10
    28	  max-work-per-tick: 64
    29	  max-ms-per-tick: 25.0
    30	  max-entities-per-second: 5
    31	  max-entities-per-chunk: 20
    32	  max-queue: 2000
    33	  max-radius: 48
    34	  max-spawns-per-second: 50
    35	`;
    36	
    37	function readPluginYml(ws) {
    38	  const p = path.join(ws, "src/main/resources/plugin.yml");
    39	  try { return fs.readFileSync(p, "utf8"); } catch { return null; }
    40	}
    41	function mainClassOf(yml) {
    42	  const m = /^main:\s*['"]?([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)+)['"]?\s*$/m.exec(yml || "");
    43	  return m ? m[1] : null;
    44	}
    45	const sourceOf = (ws, fqn) => path.join(ws, "src/main/java", ...fqn.split(".")) + ".java";
    46	
    47	/** The watchdog sources for a package (exported for tests and fixtures). */
    48	function watchdogSources(pkg) {
    49	  if (!/^[a-z_][a-z0-9_]*(\.[a-z_][a-z0-9_]*)*$/.test(pkg)) throw new Error(`bad package ${pkg}`);
    50	  return FILES.map((f) => ({ name: f, content: fs.readFileSync(path.join(SRC_DIR, f), "utf8").replace(/@PKG@/g, pkg) }));
    51	}
    52	
    53	/** Insert NxPerf.init(this) as the first statement of onEnable (or add an onEnable). Returns the new text or null if unchanged. */
    54	function patchMain(src, perfPkg, className) {
    55	  if (/\bNxPerf\s*\.\s*init\s*\(\s*this\s*\)/.test(src)) return null;
    56	  const call = `${perfPkg}.NxPerf.init(this); // Nxeon performance safety (added by the build service)`;
    57	  const m = /\bvoid\s+onEnable\s*\(\s*\)\s*(?:throws\s+[\w.,\s]+)?\{/.exec(src);
    58	  if (m) return src.slice(0, m.index + m[0].length) + `\n    ${call}` + src.slice(m.index + m[0].length);
    59	  // no onEnable: add one before the class's closing brace
    60	  const cls = new RegExp(`\\bclass\\s+${className}\\b`).exec(src);
    61	  const end = src.lastIndexOf("}");
    62	  if (!cls || end < cls.index) return null;
    63	  return `${src.slice(0, end)}\n  @Override\n  public void onEnable() {\n    ${call}\n  }\n${src.slice(end)}`;
    64	}
    65	
    66	/**
    67	 * Place the watchdog into a generated workspace. Returns { injected, reason?, pkg?, mainPatched?, configSection? }.
    68	 * Never throws for a workspace it cannot handle (validate()/javac report those); imported plugins are left alone.
    69	 */
    70	function inject(ws, rec = {}, env = process.env) {
    71	  if (!enabled(env)) return { injected: false, reason: "MB_PERF_SAFETY is off" };
    72	  if (rec.imported) return { injected: false, reason: "imported plugin (the owner's own code is not changed)" };
    73	  const main = mainClassOf(readPluginYml(ws));
    74	  if (!main) return { injected: false, reason: "no main class in plugin.yml" };
    75	  const mainFile = sourceOf(ws, main);
    76	  if (!fs.existsSync(mainFile)) return { injected: false, reason: `main class source ${main} not found` };
    77	  const pkg = main.slice(0, main.lastIndexOf("."));
    78	  const perfPkg = `${pkg}.nxperf`;
    79	  const dir = path.join(ws, "src/main/java", ...perfPkg.split("."));
    80	  fs.mkdirSync(dir, { recursive: true });
    81	  for (const f of watchdogSources(perfPkg)) fs.writeFileSync(path.join(dir, f.name), f.content);
