    86	    const lastTps = tail.at(-1)?.tps ?? null;
    87	    const lowAll = tail.length >= cfg.sustainLines && tail.every((l) => l.tps != null && l.tps < cfg.tpsFloor);
    88	    // our share: the watchdog's own_ms vs the tick length at that TPS (>= 25% = this mod is the cause)
    89	    const share = (l: NxPerfLine) => (l.ownMs ?? 0) / Math.max(50, 1000 / Math.max(0.05, l.tps ?? 20));
