    92	    }
    93	    if (lowAll) return { verdict: "ok", act: false, why: `the server is under ${cfg.tpsFloor} TPS but ${i.modName}'s own measurements say it is not the cause`, evidence: tail.map((l) => l.line), tps: lastTps };
