function flatConfig(cfg: unknown, prefix = "", out: [string, unknown][] = [], depth = 0): [string, unknown][] {
  if (!cfg || typeof cfg !== "object" || depth > 4) return out;
  for (const [k, v] of Object.entries(cfg as Record<string, unknown>).slice(0, 200)) {
    const key = prefix ? `${prefix}.${k}` : k;
    if (v && typeof v === "object" && !Array.isArray(v)) flatConfig(v, key, out, depth + 1);
    else out.push([key, v]);
  }
  return out;
}

/** Inline config written in the prompt text, e.g. "chunks-per-tick = 500, mirror-mobs = true". */
function inlineConfig(raw: string): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const m of String(raw ?? "").matchAll(/\b([a-z][a-z0-9]*(?:[-_.][a-z0-9]+)+)\s*(?:=|:|is|to)\s*(true|false|-?\d+(?:\.\d+)?)\b/gi)) {
    out[m[1].toLowerCase()] = m[2] === "true" ? true : m[2] === "false" ? false : Number(m[2]);
  }
  return out;
}

// ------------------------------------------------------------------ main ----
export function classifyPerfRisk(input: { text: string; config?: Record<string, unknown> | null }): PerfRisk {
  const raw = String(input?.text ?? "").slice(0, 20_000);
  const t = normalize(raw);
  const c: Ctx = { t, cl: clauses(t), config: { ...inlineConfig(raw), ...(input?.config ?? {}) } };
  const findings: PerfFinding[] = [];
  for (const r of RULES) {
    const hit = r.find(c);
    if (!hit) continue;
    const sev = typeof r.severity === "function" ? r.severity(hit.m ?? ([hit.match] as unknown as RegExpMatchArray), c) : r.severity;
    if (!sev) continue;
    findings.push({ id: r.id, severity: sev, title: r.title, reason: r.reason, safe: r.safe, bounds: r.bounds, match: hit.match.slice(0, 160) });
  }
  for (const [k, v] of flatConfig(c.config)) {
    for (const r of CONFIG_RULES) {
      if (!r.key.test(k)) continue;
      const sev = r.test(v);
      if (!sev || findings.some((f) => f.id === r.id)) continue;
      findings.push({ id: r.id, severity: sev, title: r.title, reason: r.reason, safe: r.safe, bounds: r.bounds, match: `${k} = ${String(v)}`.slice(0, 160) });
    }
  }
  // Mirroring + remembered chunk replay is the ChunkMirror shape: the replay finding inherits the fan-out's severity.
  const fan = findings.find((f) => f.id === "fanout-mirror");
  if (fan) for (const f of findings) if (f.id === "chunk-replay-log" || f.id === "config-mirror-mobs") f.severity = worse(f.severity, "high") as PerfSeverity;
  findings.sort((a, b) => RANK[b.severity] - RANK[a.severity] || a.id.localeCompare(b.id));
  const level = findings.reduce<PerfLevel>((acc, f) => worse(acc, f.severity), "none");
  const mustConfirm = RANK[level] >= RANK[CONFIRM_AT];
  const summary = !findings.length ? null
    : mustConfirm ? `This request implies unbounded work (${findings.filter((f) => RANK[f.severity] >= RANK[CONFIRM_AT]).map((f) => f.title.toLowerCase()).join("; ")}). Cyrus will build a bounded version unless you choose "Build anyway".`
    : `Cyrus will add limits so this stays light on the server (${findings.map((f) => f.title.toLowerCase()).join("; ")}).`;
  return { schema: "cyrus.perfrisk.v1", version: PERF_RISK_VERSION, level, findings, mustConfirm, defaultChoice: "safe", summary };
}

/**
 * The request to build for a choice. "safe" (default, also for an unknown choice) appends the findings' bounds as a
 * PERFORMANCE LIMITS block (deduped, stable order); "as_asked" returns the text unchanged. Medium/low findings always
 * get their bounds in safe mode (cheap insurance); nothing is appended when there are no findings.
 */
export function applyPerfChoice(text: string, risk: PerfRisk, choice: unknown = risk.defaultChoice): { text: string; choice: PerfChoice; bounds: string[] } {
  const ch: PerfChoice = choice === "as_asked" ? "as_asked" : "safe";
  if (ch === "as_asked" || !risk.findings.length) return { text, choice: ch, bounds: [] };
  const bounds = [...new Set(risk.findings.flatMap((f) => f.bounds))];
  return { text: `${text.trimEnd()}\n\nPERFORMANCE LIMITS (the server owner chose the safe version; these override any number above):\n${bounds.map((b) => `- ${b}`).join("\n")}`, choice: ch, bounds };
}

/** Server-side twin of the plan gate: a high/critical risk needs an explicit choice ("safe" or "as_asked") in the request. */
export function perfPreBuildCheck(risk: PerfRisk, choice: unknown): { ok: true; choice: PerfChoice } | { ok: false; status: 409; json: { error: string; code: "perf_confirm"; risk: PerfRisk } } {
  if (choice === "safe" || choice === "as_asked") return { ok: true, choice };
  if (!risk.mustConfirm) return { ok: true, choice: "safe" };
  return { ok: false, status: 409, json: { error: risk.summary ?? "This request needs a performance choice.", code: "perf_confirm", risk } };
}

/** CYRUS_PERF_SAFETY: default ON; "0" / "false" / "off" turns the whole perf-safety bundle off (kill switch). */
export function perfSafetyEnabled(env: Record<string, string | undefined> = process.env): boolean {
  const v = String(env[PERF_RISK_FLAG] ?? "").trim().toLowerCase();
  return !(v === "0" || v === "false" || v === "off");
}
