 45	const BASE: Record<Complexity, { min: [number, number]; usd: [number, number] }> = {
 46	  simple: { min: [1, 2], usd: [0.08, 0.18] },
 47	  standard: { min: [2, 4], usd: [0.15, 0.35] },
 48	  complex: { min: [3, 6], usd: [0.3, 0.6] },
 49	};
