 51	export function estimate(text: string, model: CyrusModelId, opts: { change?: boolean } = {}): Estimate {
 52	  const t = text || "";
 53	  const features: string[] = [];
 54	  let score = 0;
 55	  for (const [name, w, re] of FEATURES) if (re.test(t)) { features.push(name); score += w; }
 56	  const commands = new Set((t.match(/\/[a-z][a-z0-9_-]{1,24}/gi) || []).map((c) => c.toLowerCase())).size;
 57	  score += Math.max(0, commands - 1) * 0.5;
 58	  score += Math.min(2, Math.floor(t.length / 450));
 59	  const complexity: Complexity = score >= 7.5 ? "complex" : score >= 3 ? "standard" : "simple";
 60	  const recommended: CyrusModelId = complexity === "simple" ? "katara" : complexity === "standard" ? "saka" : "yakko";
 61	  const m = cyrusModel(model);
 62	  const b = BASE[complexity];
 63	  // A change request reads the old code first but usually writes less.
 64	  const k = opts.change ? CHANGE_COST_FACTOR : 1;
 65	  const usd: [number, number] = [round2(b.usd[0] * m.costFactor * k), round2(b.usd[1] * m.costFactor * k)];
 66	  const minutes: [number, number] = [Math.max(1, Math.round(b.min[0] * m.timeFactor * k)), Math.max(1, Math.round(b.min[1] * m.timeFactor * k))];
 67	  if (minutes[1] <= minutes[0]) minutes[1] = minutes[0] + 1;
 68	  return { complexity, score: Math.round(score * 10) / 10, features, commands, recommended, minutes, usd };
 69	}
