120	export const PROMPT_UNCLEAR_MESSAGE =
121	  "That doesn't look like a mod idea yet, so nothing was built and you weren't charged. Describe what it should do, for example: “add a 9mm pistol with ammo and a /gun give command”.";
122	
123	import { TRIGRAMS } from "./prompt-trigrams";
124	
125	const KEYBOARD_RUNS = ["asdf", "sdfg", "dfgh", "fghj", "ghjk", "hjkl", "qwer", "wert", "erty", "rtyu", "tyui", "yuio", "uiop", "zxcv", "xcvb", "cvbn", "vbnm"];
126	
127	/** Share of a word's letter triples (with edge markers) that real English words use: ~0.5-1 for words, ~0.1-0.3 for key mashing. */
128	export function wordPlausibility(w: string): number {
129	  const p = `^${w}$`;
130	  let hit = 0, all = 0;
131	  for (let i = 0; i + 3 <= p.length; i++) { all++; if (TRIGRAMS.has(p.slice(i, i + 3))) hit++; }
132	  return all ? hit / all : 1;
133	}
134	
135	/** A latin word that no human wrote: no vowel, a long consonant run, a repeated letter, keyboard mashing, a repeated chunk, or letter patterns no word uses. */
136	export function isJunkWord(w: string): boolean {
137	  if (w.length < 4) return false;
138	  if (!/^[a-z]+$/.test(w)) return false;
139	  if (w.length >= 6 && /(.{2,4})\1{1,}/.test(w) && new Set(w).size <= Math.ceil(w.length / 2)) return true; // "wasdwasd", "fsfsfsf"
140	  if (w.length >= 5 && wordPlausibility(w) < 0.42) return true; // "kajhdakj", "hdkjahdadaw"
141	  if (!/[aeiouy]/.test(w)) return true; // "hjkl", "xcvbn"
142	  if (/[^aeiouy]{6,}/.test(w)) return true; // "asdfghjkl"
143	  if (/(.)\1{3,}/.test(w)) return true; // "aaaaa"
144	  return KEYBOARD_RUNS.some((k) => w.includes(k));
145	}
