147	/** Null when the prompt may build; otherwise the customer-safe reason (always PROMPT_UNCLEAR_MESSAGE). */
148	export function promptProblem(raw: string): string | null {
149	  const text = String(raw ?? "").replace(/\s+/g, " ").trim();
150	  if (text.length < 4) return PROMPT_UNCLEAR_MESSAGE;
151	  const compact = text.replace(/\s/g, "");
152	  const letters = (text.match(/\p{L}/gu) ?? []).length;
153	  if (letters < compact.length * 0.6) return PROMPT_UNCLEAR_MESSAGE; // mostly digits and symbols
154	  const words = text.toLowerCase().match(/\p{L}[\p{L}']*/gu) ?? [];
155	  if (words.length < 2) return PROMPT_UNCLEAR_MESSAGE;
156	  const unique = new Set(words);
157	  if (unique.size < 2) return PROMPT_UNCLEAR_MESSAGE; // "yo yo yo", "gun gun gun"
158	  if (words.length >= 5 && unique.size / words.length < 0.3) return PROMPT_UNCLEAR_MESSAGE; // repetition spam
159	  const latin = words.filter((w) => /^[a-z']+$/.test(w) && w.length >= 4);
160	  if (latin.length >= 2 && latin.filter((w) => isJunkWord(w.replace(/'/g, ""))).length / latin.length >= 0.5) return PROMPT_UNCLEAR_MESSAGE;
161	  if (latin.length === 1 && words.length <= 2 && isJunkWord(latin[0].replace(/'/g, ""))) return PROMPT_UNCLEAR_MESSAGE;
162	  return null;
163	}
