  /** per-chunk cost estimate ceiling (cost.ts units); above it the pack is refused */
  maxCost: 100,
} as const;

const PATH = /^[a-z0-9_]+(\/[a-z0-9_]+){0,5}$/;
const REF = /^#?[a-z0-9_.-]+:[a-z0-9_./-]+$/;
const Path = z.string().max(64).regex(PATH, "lowercase letters, digits, _ and / (max 6 segments)");
const Ref = z.string().max(120).regex(REF, "a namespaced id like minecraft:stone or nx_abcd1234:my_biome");
const IdRef = z.string().max(120).regex(/^[a-z0-9_.-]+:[a-z0-9_./-]+$/, "a namespaced id (no #tag here)");
const Int = (min: number, max: number) => z.number().int().min(min).max(max);
const Hex = z.string().regex(/^#[0-9a-fA-F]{6}$/, "a colour like #7ba4ff");
const PropName = z.string().regex(/^[a-z0-9_]{1,32}$/);
  z.strictObject({ type: z.literal("structure_template"), id: Path, template: StructureTemplateSchema }),
  z.strictObject({ type: z.literal("structure"), id: Path, structure: StructureSchema }),
