// Cyrus Model Studio (Layer 1): the PERFORMANCE BUDGET from the plan (section 4), as numbers the viewport and the
// tests enforce. Pure + client-safe.
//   60 fps desktop for <= 64 cubes; meshes <= 150k triangles in view, <= 4 x 2048^2 channel textures, GPU memory
//   <= 512 MB; stroke-to-pixel <= 16 ms at 2048^2; three.js lazy-loaded on the studio route only; phones (< 760 px):
//   read-only orbit + approve, device pixel ratio capped at 1.5.
import type { ModelScene } from "./scene";

export const PERF_BUDGET = {
  fpsDesktop: 60,
  maxCubesAt60: 64,
  maxTriangles: 150_000,
  maxChannelTextures: 4,
  maxTextureEdge: 2048,
  gpuMemoryMB: 512,
  strokeMs: 16,
  mobileBreakpointPx: 760,
  dprDesktop: 2,
  dprMobile: 1.5,
} as const;

export const dprCap = (dpr: number, mobile: boolean) => Math.max(1, Math.min(dpr || 1, mobile ? PERF_BUDGET.dprMobile : PERF_BUDGET.dprDesktop));

export type BudgetIssue = { id: string; status: "pass" | "warn" | "fail"; value: number; limit: number; message: string };

/** GPU memory estimate: every channel texture with mipmaps (x 4/3) + positions, UVs and normals per vertex. */
export function gpuEstimateMB(scene: Pick<ModelScene, "triCount" | "tex">, channelTextures: number): number {
  const tex = channelTextures * scene.tex.w * scene.tex.h * 4 * (4 / 3);
  const geo = scene.triCount * 3 * (12 + 8 + 12);
  return Math.round(((tex + geo) / (1024 * 1024)) * 10) / 10;
}

export function sceneBudget(scene: ModelScene, channelTextures: number): BudgetIssue[] {
  const cubes = scene.kind === "creature" ? scene.parts.length : 0;
  const mb = gpuEstimateMB(scene, channelTextures);
  const edge = Math.max(scene.tex.w, scene.tex.h);
  const row = (id: string, value: number, limit: number, message: string, warnAt = limit): BudgetIssue => ({ id, value, limit, message, status: value > limit ? "fail" : value > warnAt ? "warn" : "pass" });
  return [
    row("triangles", scene.triCount, PERF_BUDGET.maxTriangles, "Triangles in view", PERF_BUDGET.maxTriangles * 0.8),
    ...(scene.kind === "creature" ? [row("cubes", cubes, PERF_BUDGET.maxCubesAt60, "Cubes (60 fps target)")] : []),
    row("texture_edge", edge, PERF_BUDGET.maxTextureEdge, "Texture size (px)"),
    row("channel_textures", channelTextures, PERF_BUDGET.maxChannelTextures, "Channel textures on the GPU"),
    row("gpu_mb", mb, PERF_BUDGET.gpuMemoryMB, "GPU memory estimate (MB)", PERF_BUDGET.gpuMemoryMB * 0.75),
  ];
}
