// Cyrus studios (R1b): where uploaded PNGs are kept. SERVER ONLY. There is no production upload storage yet
// (owner decision pending): the API answers 503 "uploads aren't switched on" unless CYRUS_UPLOAD_STORE=local on a
// NON-production host (devhost / tests), which keeps content-addressed files on local disk.
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import type { UploadStore } from "./http";

const KEY = /^cyrus\/uploads\/[A-Za-z0-9_-]{1,64}\/[0-9a-f]{64}\.png$/;

export function localUploadStore(dir: string): UploadStore {
  const root = resolve(dir);
  const at = (key: string) => { if (!KEY.test(key)) throw new Error("bad upload key"); return join(root, key); };
  return {
    async put(key, bytes) { const p = at(key); await mkdir(dirname(p), { recursive: true }); await writeFile(p, bytes); return { path: key }; },
    async get(path) { try { return await readFile(at(path)); } catch { return null; } },
  };
}

/** In-memory store for tests. */
export function memoryUploadStore(): UploadStore & { files: Map<string, Buffer> } {
  const files = new Map<string, Buffer>();
  return { files, async put(key, bytes) { if (!KEY.test(key)) throw new Error("bad upload key"); files.set(key, Buffer.from(bytes)); return { path: key }; }, async get(path) { return files.get(path) ?? null; } };
}

// Cyrus mod capabilities (networking + AI): types, validation, consent summary and the
// install gate. Pure and client-safe.
//
// A mod may only use the network through the Nxeon wrapper, with every host declared in the
// mod's `nx-capabilities.yml`. The build service validates the manifest with the same rules
// (services/modbuilder/capabilities.js); both read services/modbuilder/rules/net-policy.json,
// and test/cyrus-capabilities.test.ts checks the two implementations agree.
// Design: /root/agent-notes/cyrus-v6/capabilities/DESIGN.md. Default OFF
// (setting `cyrus_mod_networking_enabled`).
import POLICY from "../../services/modbuilder/rules/net-policy.json";

export const NET_POLICY_VERSION: string = POLICY.version;
export const MANIFEST_FILE = "nx-capabilities.yml";

export type PlayerDataCategory = "names" | "chat" | "ip";
export const PLAYER_DATA_CATEGORIES = POLICY.playerData as PlayerDataCategory[];
export const PLAYER_DATA_LABEL: Record<PlayerDataCategory, string> = {
  names: "player names and IDs",
  chat: "chat messages",
  ip: "IP addresses",
};

export type CapabilityHost = { host: string; purpose: string };
export type CapabilitySecret = { name: string; host: string; header?: string; url?: true; description: string };
export type CyrusCapabilities = {
  version: 1;
  network: { hosts: CapabilityHost[]; playerData: PlayerDataCategory[]; maxResponseKiB: number } | null;
  secrets: CapabilitySecret[];
  /** May call the Nxeon AI gateway (metered in the server owner's Cyrus tokens, off until they enable it). */
  ai: boolean;
  policy: string;
  sha256: string;
};

export type ValidationResult = { ok: true; problems: []; manifest: CyrusCapabilities } | { ok: false; problems: string[]; manifest: null };

