export const UPLOAD_LIMITS = {
  /** a 64x64 RGBA PNG is ~17 KB uncompressed; 256 KiB leaves room for unoptimised exports, not for payloads */
  maxBytes: 256 * 1024,
  sizes: [16, 32, 64] as const,
  maxChunks: 64,
  /** distinct opaque colours: pixel art uses a few ramps; a photo or a smooth render has thousands */
  maxColours: 256,
};
export type AlphaMode = "opaque" | "binary" | "translucent";
export const UPLOAD_MIME = "image/png";

