/** Unit test of the watchdog's pure half (budget, rate, lag judge, settings clamps). Plain Java: exit code 1 on failure. */
public final class NxPerfCoreTest {
  private static int failed, passed;

  private static void check(boolean ok, String what) {
    if (ok) passed++;
    else { failed++; System.out.println("FAIL " + what); }
  }

  public static void main(String[] args) {
    // Budget: resets per tick, refuses work above the per-tick amount
    NxPerfCore.Budget b = new NxPerfCore.Budget("mirror", 64);
    int got = 0;
    for (int i = 0; i < 500; i++) if (b.take(1, 1)) got++;
    check(got == 64, "budget allows exactly 64 per tick (got " + got + ")");
    check(b.denied() == 436, "budget counts denied work");
    check(b.remaining(1) == 0 && b.remaining(2) == 64, "remaining resets on a new tick");
    check(b.take(2, 64) && !b.take(2, 1), "a new tick has a full budget");
    check(!b.take(3, 65), "one request larger than the budget is refused");
    check(b.take(3, 0), "zero work is always allowed");

    // Rate: perSecond tokens, refills with time
    NxPerfCore.Rate r = new NxPerfCore.Rate(5);
    long t = 1_000_000_000L;
    int ok = 0;
    for (int i = 0; i < 50; i++) if (r.take(t)) ok++;
    check(ok == 5, "rate allows a burst of 5 (got " + ok + ")");
    check(r.take(t + 200_000_000L), "rate refills one token after 0.2 s");

